:root {
  --paper: #fffdf7;
  --ink: #253743;
  --mist: #e4f1f0;
  --sun: #f3ad45;
  --line: #c9dedc;
}

.pass {
  box-sizing: border-box;
  width: 460px;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.pass > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--mist);
  border-bottom: 2px solid var(--ink);
}

.studio-mark {
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.seat {
  padding: 4px 8px;
  color: var(--ink);
  background: var(--sun);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.pass-body {
  padding: 16px 18px 14px;
}

h1 {
  margin: 0 0 5px;
  color: var(--ink);
  font-size: 23px;
  line-height: 1.1;
}

.schedule {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.pass > footer {
  padding: 0 18px 16px;
}

button {
  width: 100%;
  padding: 9px 12px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 9px;
  font-size: 14px;
  font-weight: 700;
}
